alter table public.estate_documentation_payments add column if not exists plot_count integer not null default 1; alter table public.estate_documentation_payments add column if not exists order_id uuid; alter table public.estate_documentation_payments add column if not exists total_bundle_amount numeric not null default 0; update public.estate_documentation_payments p set plot_count=coalesce((select sum(coalesce((x->>'quantity')::integer,1)) from jsonb_array_elements(coalesce(o.items,'[]'::jsonb)) x),1), total_bundle_amount=p.amount from public.orders o where p.order_id=o.id and (p.plot_count=1 or p.total_bundle_amount=0); create or replace function public.create_documentation_payment_request(_order_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare o public.orders; es public.estate_subscriptions; dt public.documentation_types; existing public.estate_documentation_payments; plots integer; bundle numeric; begin select * into o from public.orders where id=_order_id and user_id=auth.uid(); if not found then raise exception 'Order not found'; end if; select * into es from public.estate_subscriptions where order_id=_order_id and user_id=auth.uid() order by created_at desc limit 1; if es.id is null then raise exception 'Estate subscription not found'; end if; select * into dt from public.documentation_types where price is not null and price>0 order by created_at asc limit 1; if dt.id is null then raise exception 'Documentation price has not been configured'; end if; select greatest(1,coalesce(sum(coalesce((x->>'quantity')::integer,1)),1)) into plots from jsonb_array_elements(coalesce(o.items,'[]'::jsonb)) x; bundle:=dt.price*plots; select * into existing from public.estate_documentation_payments where user_id=auth.uid() and order_id=_order_id and documentation_type_id=dt.id and status in ('pending','approved','paid','completed') order by created_at desc limit 1; if existing.id is not null then if existing.amount is distinct from bundle then update public.estate_documentation_payments set amount=bundle,total_bundle_amount=bundle,plot_count=plots,updated_at=now() where id=existing.id; end if; return jsonb_build_object('payment_id',existing.id,'amount',bundle,'status',existing.status,'reference',existing.reference,'plot_count',plots,'documentation_name',dt.name,'already_created',true); end if; insert into public.estate_documentation_payments(user_id,estate_id,documentation_type_id,amount,status,is_bundle,reference,order_id,plot_count,total_bundle_amount) values(auth.uid(),es.estate_id,dt.id,bundle,'pending',true,'DOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20)),_order_id,plots,bundle) returning * into existing; return jsonb_build_object('payment_id',existing.id,'amount',bundle,'status',existing.status,'reference',existing.reference,'plot_count',plots,'documentation_name',dt.name,'already_created',false); end; $$; grant execute on function public.create_documentation_payment_request(uuid) to authenticated; create or replace function public.get_documentation_payment_checkout(_payment_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare p public.estate_documentation_payments; dt public.documentation_types; plots integer; bundle numeric; begin select * into p from public.estate_documentation_payments where id=_payment_id and user_id=auth.uid() for update; if not found then raise exception 'Documentation payment not found'; end if; select * into dt from public.documentation_types where id=p.documentation_type_id; if not found or coalesce(dt.price,0)<=0 then raise exception 'Documentation price is not configured'; end if; select greatest(1,coalesce(sum(coalesce((x->>'quantity')::integer,1)),1)) into plots from jsonb_array_elements(coalesce((select items from public.orders where id=p.order_id),'[]'::jsonb)) x; bundle:=dt.price*plots; if p.amount is distinct from bundle or p.total_bundle_amount is distinct from bundle or p.plot_count is distinct from plots then update public.estate_documentation_payments set amount=bundle,total_bundle_amount=bundle,plot_count=plots,is_bundle=true,updated_at=now() where id=p.id; end if; return jsonb_build_object('payment_id',p.id,'order_id',p.order_id,'amount',bundle,'currency','NGN','reference',p.reference,'documentation_type_id',dt.id,'documentation_name',dt.name,'plot_count',plots,'is_bundle',true); end; $$; grant execute on function public.get_documentation_payment_checkout(uuid) to authenticated;
